-- old-writers: refuse
-- applied-by: goh state contract
CREATE TABLE refuse_agent_spawns(what TEXT NOT NULL, n INTEGER NOT NULL CHECK (n = 0)) STRICT;
INSERT INTO refuse_agent_spawns SELECT 'a row with a document, no fill, or a field left in rest', count(*) FROM agent_spawns WHERE body <> '{}' OR rest IS NULL OR json_type(rest, '$.agent_id') IS NOT NULL OR json_type(rest, '$.agent_type') IS NOT NULL OR json_type(rest, '$.agent_type_escape') IS NOT NULL OR json_type(rest, '$.apps.before') IS NOT NULL OR json_type(rest, '$.apps.exits') IS NOT NULL OR json_type(rest, '$.apps.failed') IS NOT NULL OR json_type(rest, '$.apps.missing') IS NOT NULL OR json_type(rest, '$.apps.relaunched') IS NOT NULL OR json_type(rest, '$.ci_direct') IS NOT NULL OR json_type(rest, '$.cores') IS NOT NULL OR json_type(rest, '$.declared') IS NOT NULL OR json_type(rest, '$.description') IS NOT NULL OR json_type(rest, '$.effort') IS NOT NULL OR json_type(rest, '$.event') IS NOT NULL OR json_type(rest, '$.exempt') IS NOT NULL OR json_type(rest, '$.explored') IS NOT NULL OR json_type(rest, '$.faults') IS NOT NULL OR json_type(rest, '$.first_line') IS NOT NULL OR json_type(rest, '$.items') IS NOT NULL OR json_type(rest, '$.lane') IS NOT NULL OR json_type(rest, '$.load') IS NOT NULL OR json_type(rest, '$.meter."5h"') IS NOT NULL OR json_type(rest, '$.meter."7d"') IS NOT NULL OR json_type(rest, '$.meter.age_h') IS NOT NULL OR json_type(rest, '$.meter.ok') IS NOT NULL OR json_type(rest, '$.meter.read_at') IS NOT NULL OR json_type(rest, '$.model') IS NOT NULL OR json_type(rest, '$.model_id') IS NOT NULL OR json_type(rest, '$.no_item_why') IS NOT NULL OR json_type(rest, '$.pool.said') IS NOT NULL OR json_type(rest, '$.pool.why') IS NOT NULL OR json_type(rest, '$.profile') IS NOT NULL OR json_type(rest, '$.profile_why') IS NOT NULL OR json_type(rest, '$.prompt_sha') IS NOT NULL OR json_type(rest, '$.report') IS NOT NULL OR json_type(rest, '$.route') IS NOT NULL OR json_type(rest, '$.scratch_loose') IS NOT NULL OR json_type(rest, '$.session_id') IS NOT NULL OR json_type(rest, '$.status') IS NOT NULL OR json_type(rest, '$.subagent_type') IS NOT NULL OR json_type(rest, '$.tags') IS NOT NULL OR json_type(rest, '$.time') IS NOT NULL OR json_type(rest, '$.tokens.cache_creation') IS NOT NULL OR json_type(rest, '$.tokens.cache_read') IS NOT NULL OR json_type(rest, '$.tokens.input') IS NOT NULL OR json_type(rest, '$.tokens.output') IS NOT NULL OR json_type(rest, '$.tokens.total') IS NOT NULL OR json_type(rest, '$.tokens_settled') IS NOT NULL OR json_type(rest, '$.tool_use_id') IS NOT NULL;
INSERT INTO refuse_agent_spawns SELECT 'a spawn whose item is in no row', count(*) FROM agent_spawns s WHERE s.item IS NOT NULL AND NOT EXISTS (SELECT 1 FROM spawn_lists l WHERE l.n = s.n AND l.kind = 'item' AND l.value = s.item);
DROP TABLE refuse_agent_spawns;
DROP TRIGGER agent_spawns_fill;
DROP TRIGGER agent_spawns_refill;
DROP TRIGGER agent_spawns_bad;
ALTER TABLE agent_spawns DROP COLUMN body;
